import{c as a,Q as o,j as t,m as c}from"./chunks/framework.Cr5Oofs_.js";const h=JSON.parse('{"title":"版本命名规则","description":"介绍 ClickMouse 版本命名规则。","frontmatter":{"title":"版本命名规则","description":"介绍 ClickMouse 版本命名规则。","layout":"doc"},"headers":[],"relativePath":"zh-CN/guide/version-naming.md","filePath":"zh-CN/guide/version-naming.md"}'),p={name:"zh-CN/guide/version-naming.md"};function r(i,e,d,n,s,l){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="版本命名规则" tabindex="-1">版本命名规则 <a class="header-anchor" href="#版本命名规则" aria-label="Permalink to &quot;版本命名规则&quot;">​</a></h1><p>clickmouse版本格式为：<code>A.B.C.D[(alpha | beta |.dev | rc) E]</code></p><h2 id="正式版本" tabindex="-1">正式版本 <a class="header-anchor" href="#正式版本" aria-label="Permalink to &quot;正式版本&quot;">​</a></h2><p>正式版不带.dev、alpha、beta或rc后缀。</p><p>A位代表有重大更新，有代码级的变动。如1.0升级到2.0就重构了代码。</p><p>B位代表有普通更新，通常是更新一些大功能。</p><p>C位代表有修复更新，通常会更新一些小功能和一些bug。</p><p>D位代表版本代号，通常每A, B, C位有变动时候+1。也有可能A, B, C位没有变动，D位+1，这代表紧急更新，通常是修复几个重大影响的bug。</p><h2 id="测试版本" tabindex="-1">测试版本 <a class="header-anchor" href="#测试版本" aria-label="Permalink to &quot;测试版本&quot;">​</a></h2><p>测试版本带.dev、alpha、beta或rc后缀。</p><p>通常前面的<code>A.B.C.D</code>在一个测试周期内不变，代表下一个版本。</p><p><code>.dev</code>代表早期开发更新，功能不稳定，bug很多，位于版本项目初期。这阶段新增的功能将会被放到实验室中，并默认关闭。</p><p><code>alpha</code>代表晚期开发更新，功能不完善，bug较多，位于版本项目早期。这阶段新增的功能将会被放到实验室中，并默认关闭。</p><p><code>beta</code>代表发布测试更新，功能完善，bug较少，不会再新增功能，位于版本项目中期，并且会逐步合并实验室中的feature。</p><p><code>rc</code>代表预备发布版本，功能完善，bug较少，会修复一些重要安全问题或bug，最接近正式版，即将发布正式版，位于版本项目末期。</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>rc最后一个版本将直接合并到测试版；功能完全一样。</p></div>',16)])])}const m=a(p,[["render",r]]);export{h as __pageData,m as default};
